      if (!all.length) return html + '<div class="card">' + UI.empty('receipt', 'Noch keine Rechnungen', 'Rechnungen entstehen aus Projekten oder Angeboten – Kundendaten, Positionen und Anzahlungen werden übernommen.', '<button class="btn primary" data-act="newInvoice">' + ic('plus') + 'Rechnung erstellen</button>') + '</div>';
      return html + '<div class="card pad0"><div class="tbl-wrap"><table class="tbl cards"><thead><tr>' + H.th('rechnungen', 'number', 'Nr.') + '<th>Art</th>' + H.th('rechnungen', 'company', 'Kunde') + H.th('rechnungen', 'date', 'Datum') + H.th('rechnungen', 'due', 'Fällig') + '<th>Status</th>' + H.th('rechnungen', 'gross', 'Brutto', 'num') + H.th('rechnungen', 'open', 'Offen', 'num') + '</tr></thead><tbody>' +
        (rows.length ? rows.map(i => '<tr class="click" data-href="rechnung-' + i.id + '"><td class="strong">' + esc(i.number || 'Entwurf') + '</td><td class="hide-m small">' + esc(L.labelOf(L.INVOICE_TYPES, i.type)) + '</td><td data-l="Kunde">' + esc(O.companyName(i.companyId) || i.customerName || '') + '</td><td class="hide-m">' + F.date(i.date) + '</td><td data-l="Fällig">' + F.date(i.dueDate) + '</td><td>' + H.istatus(i) + '</td><td class="num" data-l="Brutto">' + F.money(L.totals(i).gross) + '</td><td class="num hide-m">' + (L.openAmount(i) ? F.money(L.openAmount(i)) : '–') + '</td></tr>').join('') : '<tr><td colspan="8" class="faint center" style="padding:20px">Keine Rechnungen in dieser Ansicht.</td></tr>') + '</tbody></table></div></div>';
